// ScoreboardServiceHandler is an implementation of the scoreboard.v1.ScoreboardService service.
type ScoreboardServiceHandler interface {
	// GetInstance describes this instance: mode, features, branding.
	GetInstance(context.Context, *connect.Request[v1.GetInstanceRequest]) (*connect.Response[v1.GetInstanceResponse], error)
	// CreateGroup makes a group and makes the caller its first owner device.
	// Fails with PERMISSION_DENIED when group creation is off (or single mode).
	CreateGroup(context.Context, *connect.Request[v1.CreateGroupRequest]) (*connect.Response[v1.CreateGroupResponse], error)
	// Join issues a member device for the group the office code belongs to. In
	// single mode the code is ignored.
	Join(context.Context, *connect.Request[v1.JoinRequest]) (*connect.Response[v1.JoinResponse], error)
	// ClaimOwner makes a browser an owner using the owner link's token.
	ClaimOwner(context.Context, *connect.Request[v1.ClaimOwnerRequest]) (*connect.Response[v1.ClaimOwnerResponse], error)
	GetGroup(context.Context, *connect.Request[v1.GetGroupRequest]) (*connect.Response[v1.GetGroupResponse], error)
	// UpdateGroup renames the group. Owners only.
	UpdateGroup(context.Context, *connect.Request[v1.UpdateGroupRequest]) (*connect.Response[v1.UpdateGroupResponse], error)
	// DeleteGroup deletes the group and everything in it. Owners only.
	DeleteGroup(context.Context, *connect.Request[v1.DeleteGroupRequest]) (*connect.Response[v1.DeleteGroupResponse], error)
	// RotateLink replaces the office, dashboard or owner link; the old one stops
	// working. Owners only.
	RotateLink(context.Context, *connect.Request[v1.RotateLinkRequest]) (*connect.Response[v1.RotateLinkResponse], error)
	// ListDevices lists the group's devices. Owners only.
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	// RemoveDevice removes a device: owners any, everyone their own (leaving).
	RemoveDevice(context.Context, *connect.Request[v1.RemoveDeviceRequest]) (*connect.Response[v1.RemoveDeviceResponse], error)
	// CreatePlayer adds a player, or returns the existing one with that name
	// (case and invisible characters ignored) with existed = true.
	CreatePlayer(context.Context, *connect.Request[v1.CreatePlayerRequest]) (*connect.Response[v1.CreatePlayerResponse], error)
	UpdatePlayer(context.Context, *connect.Request[v1.UpdatePlayerRequest]) (*connect.Response[v1.UpdatePlayerResponse], error)
	CreateGame(context.Context, *connect.Request[v1.CreateGameRequest]) (*connect.Response[v1.CreateGameResponse], error)
	UpdateGame(context.Context, *connect.Request[v1.UpdateGameRequest]) (*connect.Response[v1.UpdateGameResponse], error)
	// GetGame is the game page in one call: leaderboard, handicaps, tournaments
	// and recent rounds.
	GetGame(context.Context, *connect.Request[v1.GetGameRequest]) (*connect.Response[v1.GetGameResponse], error)
	// GetGameVersion is a cheap change counter for polling screens.
	GetGameVersion(context.Context, *connect.Request[v1.GetGameVersionRequest]) (*connect.Response[v1.GetGameVersionResponse], error)
	CreateTournament(context.Context, *connect.Request[v1.CreateTournamentRequest]) (*connect.Response[v1.CreateTournamentResponse], error)
	UpdateTournament(context.Context, *connect.Request[v1.UpdateTournamentRequest]) (*connect.Response[v1.UpdateTournamentResponse], error)
	ListRounds(context.Context, *connect.Request[v1.ListRoundsRequest]) (*connect.Response[v1.ListRoundsResponse], error)
	// CreateRound records a round and updates every rating it touches.
	CreateRound(context.Context, *connect.Request[v1.CreateRoundRequest]) (*connect.Response[v1.CreateRoundResponse], error)
	// UpdateRound edits a round; changing teams or winner re-rates the game.
	UpdateRound(context.Context, *connect.Request[v1.UpdateRoundRequest]) (*connect.Response[v1.UpdateRoundResponse], error)
	// DeleteRound soft-deletes a round (ratings are recalculated without it).
	DeleteRound(context.Context, *connect.Request[v1.DeleteRoundRequest]) (*connect.Response[v1.DeleteRoundResponse], error)
	RestoreRound(context.Context, *connect.Request[v1.RestoreRoundRequest]) (*connect.Response[v1.RestoreRoundResponse], error)
	GetPlayerStats(context.Context, *connect.Request[v1.GetPlayerStatsRequest]) (*connect.Response[v1.GetPlayerStatsResponse], error)
	// PreviewRound is the chance that team A beats team B, given today's ratings.
	PreviewRound(context.Context, *connect.Request[v1.PreviewRoundRequest]) (*connect.Response[v1.PreviewRoundResponse], error)
	// SuggestTeams splits players into the two fairest teams.
	SuggestTeams(context.Context, *connect.Request[v1.SuggestTeamsRequest]) (*connect.Response[v1.SuggestTeamsResponse], error)
	GetDashboard(context.Context, *connect.Request[v1.GetDashboardRequest]) (*connect.Response[v1.GetDashboardResponse], error)
	GetDashboardGame(context.Context, *connect.Request[v1.GetDashboardGameRequest]) (*connect.Response[v1.GetDashboardGameResponse], error)
	GetDashboardGameVersion(context.Context, *connect.Request[v1.GetDashboardGameVersionRequest]) (*connect.Response[v1.GetDashboardGameVersionResponse], error)
}

